WITH rel AS (SELECT json_extract_string(state,'$.prepaid') AS p, SUM(CAST(json_extract(state,'$.amount') AS BIGINT)) AS released FROM objects WHERE object_type = 'prepaid_release' GROUP BY 1) SELECT COALESCE(json_extract_string(i.state,'$.number'), '') AS invoice, COALESCE(json_extract_string(c.state,'$.name'), '') AS supplier, json_extract_string(pc.state,'$.account') AS account, json_extract_string(pc.state,'$.start') AS start, json_extract_string(pc.state,'$.end') AS until, CAST(json_extract(pc.state,'$.amount') AS BIGINT) AS amount, COALESCE(rel.released, 0) AS released, CAST(json_extract(pc.state,'$.amount') AS BIGINT) - COALESCE(rel.released, 0) AS remaining, pc.object_id AS _of FROM objects pc LEFT JOIN rel ON rel.p = pc.object_id LEFT JOIN objects i ON i.object_id = json_extract_string(pc.state,'$.invoice') LEFT JOIN objects c ON c.object_id = json_extract_string(i.state,'$.supplier') WHERE pc.object_type = 'prepaid_cost' ORDER BY json_extract_string(pc.state,'$.status'), json_extract_string(pc.state,'$.start'), pc.object_id
